      "type": "news",
      "source": "NeurIPS Blog",
      "title": "Making AI Science More Accessible at NeurIPS",
      "summary": "By Julien Besset, Science Communicator at Mila and David Rolnick, McGill University and Program Chair at NeurIPS 2026 Authors of accepted papers at NeurIPS are now asked to write a short overview of their work for a non-technical audience (also called a lay summary). This initiative aims to increase the visibility of AI research by […]",
      "summary_ko": "NeurIPS Blog가 공개한 소식으로, 미분류 분야의 분류 검토 필요 변화에 초점을 둡니다. 새로운 방법과 실험 결과, 실제 활용 가능성을 중심으로 핵심 내용을 살펴봅니다.",
      "motivation_ko": "새 연구 결과나 시스템이 기존 접근법의 어떤 한계를 해결하며 실제 적용에 어떤 변화를 만드는지 확인할 필요가 있습니다.",
      "contribution_ko": "실험과 분석을 통해 기존 접근법의 동작 특성을 설명하고 개선 가능성을 뒷받침하는 근거를 제공합니다. 핵심 검증 대상은 제안된 접근법의 성능과 실제 적용 가능성입니다.",
      "url": "https://blog.neurips.cc/2026/10/12/making-ai-science-more-accessible-at-neurips/",
      "published_at": "2026-10-12T19:05:26+00:00",
